function fullPageLoading() {
    jQuery("body").append('<div id="loader_wrapper"></div>');
    jQuery("#loader_wrapper").append('<div id="loader"><i class="fa fa-3x fa-circle-o-notch fa-spin fa-spin-3x"></i></div>');
}

function fullPageUnLoading() {
    jQuery("#loader_wrapper").remove();
}

function openPopup(url, w, h){
    var dualScreenLeft = window.screenLeft != undefined ? window.screenLeft : screen.left;
    var dualScreenTop = window.screenTop != undefined ? window.screenTop : screen.top;
    width = window.innerWidth ? window.innerWidth : document.documentElement.clientWidth ? document.documentElement.clientWidth : screen.width;
    height = window.innerHeight ? window.innerHeight : document.documentElement.clientHeight ? document.documentElement.clientHeight : screen.height;
    
    var left = ((width / 2) - (w / 2)) + dualScreenLeft;
    var top = ((height / 2) - (h / 2)) + dualScreenTop;
    var windowFeatures = "status=no,height=" + height + ",width=" + w + ",height=" + h + ",resizable=no, left=" + left + ", top=" + top + ", screenX=" + left + ", screenY=" + top + ", toolbar=no, menubar=no, scrollbars=no, location=no, directories=no";

    var newWindow = window.open(url, 'share', windowFeatures);
    if (window.focus) newWindow.focus();

    return false;
}

function facebookShare(url) {
    return openPopup('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent( url ), 520, 350);
}

function twitterShare(url, text) {
    return openPopup('https://twitter.com/share?url=' + encodeURIComponent( url ) + '&text=' + text + '&hashtags=DoYouSlim', 520, 350);
}

function googleShare(url) {
    return openPopup('https://plus.google.com/share?url=' + encodeURIComponent( url ), 520, 350);
}

jQuery(document).ready(function() {
    jQuery('.lazy').Lazy();

    // countdown
    if (jQuery('#countdown').length > 0) {
        var targetDate = jQuery('.countdown').data('date');
        
        if(targetDate !== undefined){
            var eventDate = new Date(targetDate);
        }
        else{
            var eventDate = new Date();
            eventDate.setHours(23,59,59,0);
        }
    
        jQuery('#countdown').countdown(eventDate, function(event) {
            var now = new Date().getTime();
            
            // Find the distance between now and the count down date
            var distance = eventDate - now;

            // Time calculations for days, hours, minutes and seconds
            var days = Math.floor(distance / (1000 * 60 * 60 * 24));
            var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            var seconds = Math.floor((distance % (1000 * 60)) / 1000);

            if( days > 0 ){
                var $this = jQuery(this).html(
                    '<span>'+days+'</span> j '
                    + '<span>'+hours+'</span> H '
                    + '<span>'+minutes+'</span> mn '
                    + '<span>'+seconds+'</span> s'
                );
            } else {
                var $this = jQuery(this).html(
                    '<span>'+hours+'</span> H '
                    + '<span>'+minutes+'</span> mn '
                    + '<span>'+seconds+'</span> s'
                );
            }
        });
    }

    // scrollToTop
    if (jQuery('.scrollToTop').length > 0) {
        //Check to see if the window is top if not then display button
    	jQuery(window).scroll(function(){
    		if (jQuery(this).scrollTop() > 100) {
    			jQuery('.scrollToTop').fadeIn();
    		} else {
    			jQuery('.scrollToTop').fadeOut();
    		}
    	});
    	
    	//Click event to scroll to top
    	jQuery('.scrollToTop').click(function(){
    		jQuery('html, body').animate({scrollTop : 0},800);
    		return false;
    	});
    }

	// carousel
    if (jQuery('.advertisers-carousel').length > 0) {
        jQuery(".advertisers-carousel").owlCarousel({
            navigation: false,
            pagination: false,
            items: 3,
            autoPlay: 4000,
            stopOnHover: true
        });
    }

	// countdown
	jQuery('[data-countdown]').each(function() {
    	var $this = jQuery(this), finalDate = jQuery(this).data('countdown');
    	$this.countdown(finalDate, function(event) {
        	$this.html(event.strftime('<span class="cdown day"><span class="time-count">%-D</span> <span class="cdown-tex">D</span></span> <span class="cdown hour"><span class="time-count separator">%-H</span> <span class="cdown-tex">H</span></span> <span class="cdown minutes"><span class="time-count separator">%M</span> <span class="cdown-tex">Min</span></span> <span class="cdown"><span class="time-count">%S</span> <span class="cdown-tex">Sec</span></span>'));
        });
    });

	// notify
	jQuery('[data-notify]').each(function() {
        var el = jQuery(this);
        var url = el.data('url');
        var type = el.data('type');
        
        jQuery.ajax({
            dataType: "json",
            type: 'POST',
			url: url,
			data: 'type='+type,
        })
        .done(function(rep) {
            if( rep.success ){
                setTimeout(function() {
                    jQuery.notify({
                        icon: 'fa fa-2x fa-shopping-cart',
                        title: rep.title,
                        message: rep.content,
                    },{
                        type: 'notify',
                        placement: {
                            from: "bottom",
                            align: "right"
                        },
                        delay: 6000,
                        timer: 1000,
                        template: '<div data-notify="container" class="col-xs-11 col-sm-3 alert alert-{0}" role="alert">' +
                            '<button type="button" aria-hidden="true" class="close" data-notify="dismiss">×</button>' +
                        	'<i data-notify="icon"></i> ' +
                        	'<span data-notify="title">{1}</span> ' +
                        	'<span data-notify="message">{2}</span>' +
                        '</div>'
                    });
                }, 13000);
            }
        });
    });
    
	// optin
	jQuery('[data-optin]').each(function() {
        var el = jQuery(this);
        var optinUrl = el.data('optin');
        var termsUrl = el.data('terms');
        var customer = el.data('customer');

    	jQuery.ajax({
    		dataType: "json",
    		type: 'POST',
    		url: optinUrl,
    	})
    	.done(function(rep) {
            if( rep.success ){
        		jQuery("body").append(rep.content);			
        		jQuery("#appModal").modal('show');
    
            	jQuery('#btnAcceptTerms').click(function(){
                	jQuery.ajax({
                		dataType: "json",
                		type: 'POST',
                		url: termsUrl,
                		data: 'customer='+customer+'&source='+encodeURIComponent(jQuery(location).attr('href')),
                	})
                	.done(function(rep) {
                		jQuery("#appModal").modal('hide');
                	});
            	});
            }
    	});
    });
    
	// catcher
	jQuery('[data-catcher]').each(function() {
        var el = jQuery(this);
        var catcherUrl = el.data('catcher');

    	jQuery.ajax({
    		dataType: "json",
    		type: 'POST',
            url: catcherUrl,
    	})
    	.done(function(rep) {
    		if( rep.success ){
        		jQuery("body").append(rep.content);			
        		jQuery("#appModal").modal('show');
            }
    	});
    });
        
	// modal links
	jQuery('a.videoShow').click(function () {
		var el = jQuery( this );
    	jQuery("#appModal").remove();
    	
    	jQuery.ajax({
    		dataType: "json",
    		type: 'POST',
			url: el.attr('href'),
    		data: 'file='+el.data('file'),
    	})
    	.done(function(rep) {
    		jQuery("body").append(rep.content);			
    		jQuery("#appModal").modal('show');
    	});

        return false;
    });
    
	// modal links
	jQuery('a.modalLink').click(function () {
		var el = jQuery( this );
        jQuery("#appModal").remove();
		
		jQuery.ajax({
			dataType: "json",
			type: 'POST',
			url: el.attr('href'),
		})
		.done(function(rep) {
			jQuery("body").append(rep.content);			
			jQuery("#appModal").modal('show');
		});
	
		return false;
	});

	// facebook share
	jQuery(".facebookShare").click(function(){
    	return facebookShare( jQuery('meta[property="og:url"]').attr('content') );
    });

	// twitter share
	jQuery(".twitterShare").click(function(){
    	return twitterShare( jQuery('meta[property="og:url"]').attr('content'), jQuery('meta[property="og:title"]').attr('content') );
    });

	// google share
	jQuery(".googleShare").click(function(){
    	return googleShare( jQuery('meta[property="og:url"]').attr('content') );
    });

	jQuery('#feedback > .title').on('click',function(e){
    	jQuery("#feedback > .content").slideToggle('slow');
    	if(jQuery("#feedback").hasClass('feedbackOpen')){
        	jQuery("#feedback").addClass('feedbackClose').removeClass('feedbackOpen');
    	}
    	else{
        	jQuery("#feedback").addClass('feedbackOpen').removeClass('feedbackClose');
    	}
    });

	jQuery('#modal-cta-default-lnk').on('click',function(e){
        if(jQuery.cookie("cookie_consent_key") !== undefined){
            jQuery(this).attr('href', jQuery(this).attr('href')+'&cck='+jQuery.cookie("cookie_consent_key"));
        }
    });
	jQuery('#modal-cta-lnk').on('click',function(e){
        if(jQuery.cookie("cookie_consent_key") !== undefined){
            jQuery(this).attr('href', jQuery(this).attr('href')+'&cck='+jQuery.cookie("cookie_consent_key"));
        }
    });
	jQuery('#continueToCart-lnk').on('click',function(e){
        if(jQuery.cookie("cookie_consent_key") !== undefined){
            jQuery(this).attr('href', jQuery(this).attr('href')+'&cck='+jQuery.cookie("cookie_consent_key"));
        }
    });
});
function initModalLink(){
	jQuery('a.modalLink').click(function () {
		var el = jQuery( this );
        jQuery("#appModal").remove();
		
		jQuery.ajax({
			dataType: "json",
			type: 'POST',
			url: el.attr('href'),
		})
		.done(function(rep) {
			jQuery("body").append(rep.content);			
			jQuery("#appModal").modal('show');

        	initCookieConsentSave();
        	initCookieConsentAcceptAll();
        	initCookieConsentRejectAll();
		});
	
		return false;
	});
}

function initCookieConsentModal(){
	jQuery('a.cookieConsentModal').click(function () {
		var el = jQuery( this );
        jQuery("#appModal").remove();
		
		jQuery.ajax({
			dataType: "json",
			type: 'POST',
			url: el.attr('href'),
		})
		.done(function(rep) {
			jQuery("body").append(rep.content);			
			jQuery("#appModal").modal('show');

        	initCookieConsentSave();
        	initCookieConsentAcceptAll();
        	initCookieConsentRejectAll();
		});
	
		return false;
	});
}

function initCookieConsentAcceptAll(){
	jQuery('a.cookieConsentAcceptAll').click(function () {
		var el = jQuery( this );
		
		jQuery.ajax({
			dataType: "json",
			type: 'POST',
			url: el.attr('href'),
			data: 'value=1',
		})
		.done(function(rep) {
			jQuery("#appModal").modal('hide');
            jQuery(".cookie_consent").hide();
		});
	
		return false;
	});
}

function initCookieConsentRejectAll(){
	jQuery('a.cookieConsentRejectAll').click(function () {
		var el = jQuery( this );
		
		jQuery.ajax({
			dataType: "json",
			type: 'POST',
			url: el.attr('href'),
			data: 'value=0',
		})
		.done(function(rep) {
			jQuery("#appModal").modal('hide');
            jQuery(".cookie_consent").hide();
		});
	
		return false;
	});
}

function initCookieConsentSave(){
	jQuery('a.cookieConsentSave').click(function () {
		var el = jQuery( this );
		
        var values = {};
        jQuery('#rules input:checkbox').each(function(){
            if( jQuery(this).is(':checked') ){
                values[jQuery(this).attr('name')] = jQuery(this).val();
            }
            else{
                values[jQuery(this).attr('name')] = 0;
            }
        });
            
		jQuery.ajax({
			dataType: "json",
			type: 'POST',
			url: el.attr('href'),
    		data: values,
		})
		.done(function(rep) {
			jQuery("#appModal").modal('hide');
            jQuery(".cookie_consent").hide();
		});
	
		return false;
	});
}

$(document).ready(function() {    
    if(jQuery(".cookie_consent").length){
        if(jQuery.cookie("cookie_consent") === undefined){
            var banner = jQuery(".cookie_consent").data('banner');
            
            jQuery.ajax({
                dataType: "json",
                type: 'POST',
    			url: banner,
            })
            .done(function(rep) {
                if( rep.success ){
        			jQuery(".cookie_consent").html( rep.content ).show();
                }
                else{
        			jQuery(".cookie_consent").hide();
                }
                	
            	initModalLink();
            	initCookieConsentModal();

            	initCookieConsentSave();
            	initCookieConsentAcceptAll();
            	initCookieConsentRejectAll();
            });
        }
        else{
            initCookieConsentModal();
        
        	initCookieConsentSave();
        	initCookieConsentAcceptAll();
        	initCookieConsentRejectAll();
        }
    }
    else{
        initCookieConsentModal();
    
    	initCookieConsentSave();
    	initCookieConsentAcceptAll();
    	initCookieConsentRejectAll();
    }
});
